export default async function next({ mode, repositories, callbackUrl, acknowledge }, ctx) {
  if (
    !["register", "delete"].includes(mode) ||
    !Array.isArray(repositories) ||
    !repositories.length ||
    repositories.some((x) => typeof x !== "string" || !/^[-\w.]+\/[-\w.]+$/.test(x)) ||
    (mode === "register" && (!/^https:\/\//.test(callbackUrl) || callbackUrl.includes("YOUR_")))
  )
    throw Error("Configure mode, owner/repository entries and HTTPS callback URL");
  let s = await ctx.state.get("github-hooks");
  if (!s) {
    s = {
      mode,
      repositories,
      callbackUrl,
      index: 0,
      page: 1,
      hooks: null,
      hookIndex: 0,
      pending: null,
    };
    await ctx.state.set("github-hooks", s);
  }
  if (
    s.mode !== mode ||
    JSON.stringify(s.repositories) !== JSON.stringify(repositories) ||
    s.callbackUrl !== callbackUrl
  )
    throw Error("Finish or reconcile the existing management run before changing configuration");
  if (s.pending) {
    if (s.pending.key !== acknowledge) throw Error("Inspect GitHub hook action " + s.pending.key);
    if (s.pending.type === "register") s.index++;
    else s.hookIndex++;
    s.pending = null;
    await ctx.state.set("github-hooks", s);
  }
  while (s.index < s.repositories.length) {
    const repo = s.repositories[s.index],
      base =
        "https://api.github.com/repos/" +
        repo.split("/").map(encodeURIComponent).join("/") +
        "/hooks";
    if (s.mode === "register")
      return {
        action: "register",
        url: base,
        body: {
          name: "web",
          active: true,
          events: ["push", "pull_request"],
          config: { url: s.callbackUrl, content_type: "json", insecure_ssl: "0" },
        },
        key: "register:" + repo,
      };
    if (s.hooks === null)
      return { action: "list", url: base + "?per_page=100&page=" + s.page, body: {}, key: "" };
    if (s.hookIndex < s.hooks.length) {
      const hook = s.hooks[s.hookIndex];
      return {
        action: "delete",
        url: base + "/" + encodeURIComponent(String(hook)),
        body: {},
        key: "delete:" + repo + ":" + hook,
      };
    }
    if (s.hooks.length === 100) {
      s.page = 1;
      s.hooks = null;
      s.hookIndex = 0;
    } else {
      s.index++;
      s.page = 1;
      s.hooks = null;
      s.hookIndex = 0;
    }
    await ctx.state.set("github-hooks", s);
  }
  await ctx.state.set("github-hooks", null);
  return { action: "done", url: "https://api.github.com/", body: {}, key: "" };
}

