export default async function mark({ key, type }, ctx) {
  const s = await ctx.state.get("github-hooks");
  if (!s || s.pending) throw Error("Hook state mismatch");
  s.pending = { key, type };
  await ctx.state.set("github-hooks", s);
  return { ok: true };
}

