export default async function list({ body }, ctx) {
  if (
    !Array.isArray(body) ||
    body.some((x) => !x || (!Number.isSafeInteger(x.id) && typeof x.id !== "string"))
  )
    throw Error("Invalid GitHub hook list");
  const s = await ctx.state.get("github-hooks");
  if (!s || s.hooks !== null) throw Error("Hook state mismatch");
  s.hooks = body.map((x) => x.id);
  s.hookIndex = 0;
  await ctx.state.set("github-hooks", s);
  return { ok: true };
}

