export default async function event({ body, headers, chatId, acknowledge }, ctx) {
  if (!/^-?\d+$/.test(chatId)) throw Error("Configure Telegram chat ID");
  const type = Object.entries(headers ?? {}).find(
      ([k]) => k.toLowerCase() === "x-github-event",
    )?.[1],
    delivery = Object.entries(headers ?? {}).find(
      ([k]) => k.toLowerCase() === "x-github-delivery",
    )?.[1],
    s = (await ctx.state.get("github-notices")) ?? { pending: null, queue: [], done: [] };
  if (
    delivery &&
    ["push", "pull_request"].includes(type) &&
    !s.done.includes(delivery) &&
    !s.queue.some((x) => x.delivery === delivery)
  ) {
    const repo = body?.repository?.full_name;
    if (typeof repo !== "string") throw Error("Missing repository");
    let text;
    if (type === "push") {
      const c = body.commits?.[0];
      if (c)
        text =
          "[GitHub push] " +
          repo +
          "\n" +
          (c.author?.name ?? "") +
          "\n" +
          (c.message ?? "") +
          "\nModified: " +
          (c.modified ?? []).join(", ") +
          "\n" +
          (c.url ?? "");
    } else {
      const p = body.pull_request;
      if (!p) throw Error("Missing pull request");
      text =
        "[GitHub pull request] " +
        repo +
        "\n" +
        (body.action ?? "") +
        " #" +
        (p.number ?? body.number ?? "") +
        " " +
        (p.title ?? "") +
        "\n" +
        (p.html_url ?? "");
    }
    if (text) {
      s.queue.push({ delivery, text });
      await ctx.state.set("github-notices", s);
    }
  }
  if (s.pending) {
    if (s.pending !== acknowledge) throw Error("Inspect Telegram delivery " + s.pending);
    s.done.push(s.pending);
    s.queue = s.queue.filter((x) => x.delivery !== s.pending);
    s.pending = null;
    await ctx.state.set("github-notices", s);
  }
  if (!s.queue.length) return { send: false, text: "No notification", delivery: "" };
  const x = s.queue[0];
  s.pending = x.delivery;
  await ctx.state.set("github-notices", s);
  return { send: true, text: x.text, delivery: x.delivery };
}

