export default async function done({ delivery }, ctx) {
  const s = await ctx.state.get("github-notices");
  if (!s || s.pending !== delivery) throw Error("Notification state mismatch");
  s.done.push(delivery);
  s.queue.shift();
  s.pending = null;
  await ctx.state.set("github-notices", s);
  return { ok: true };
}
